def render_situation(templates, situation, subject):
    """상황 문장 선택 + subject 처리 — NoticeSpeechComposer 생산자 가드(§3.6).

    표 밖 상황 → InvalidSpeechSituation. 문장에 `{subject}` 자리가 있으면 subject 는 비어 있지 않은
    문자열이어야 하고(None·공백만 → 같은 InvalidSpeechSituation 재사용), 자리가 없으면 subject 를 무시한다.
    판정 기준은 별도 집합이 아니라 문장 템플릿의 `{subject}` 포함 여부다(허용 상황 정본 = templates).
    """
    if situation not in templates:
        raise InvalidSpeechSituation(f"안내 발화 표에 없는 상황입니다: {situation}")
    line = templates[situation]
    if "{subject}" not in line:
        return line
    if subject is None or not subject.strip():
        raise InvalidSpeechSituation(f"상황 문장이 요구하는 subject 가 비어 있습니다: {situation}")
    return line.replace("{subject}", subject)
